import type { Wall, Point } from './types';
import { distance, wallRectangle } from './geometry';
import { getCurvedWallGeometry } from './curvedWallGeometry';
import { buildContourPolygon, orderWallsIntoLoop, polygonArea } from './contourUtils';

// ============ ثوابت ============
const EPS_DET = 1e-9;
const EPS_LEN = 1e-6;
const EPS_POINT = 1e-6;
const TOL_CONNECT = 0.001;   // 1mm — اتصال Primitive بالذي يليه
const LOOP_TOL = 0.05;       // 5cm — فجوة الحلقة الأصلية
const MIN_AREA = 0.001;      // 10cm² — رفض المساحات المنحلة

// ============ أنواع ============
type LinePrim = { kind: 'line'; a: Point; b: Point };
type ArcPrim = { kind: 'arc'; center: Point; radius: number; thetaStart: number; thetaEnd: number };
type Primitive = LinePrim | ArcPrim;

interface WallFace {
  startPoint: Point;
    endPoint: Point;
      startTangent: Point;
        endTangent: Point;
          arc?: { center: Point; radius: number; thetaStart: number; thetaEnd: number };
          }

          // ============ أدوات ============
          const dist2D = (a: Point, b: Point) => Math.hypot(a.x - b.x, a.y - b.y);

          const ptAtAngle = (c: Point, r: number, t: number): Point => ({
            x: c.x + r * Math.cos(t),
              y: c.y + r * Math.sin(t),
              });

              const primStart = (p: Primitive): Point =>
                p.kind === 'line' ? p.a : ptAtAngle(p.center, p.radius, p.thetaStart);

                const primEnd = (p: Primitive): Point =>
                  p.kind === 'line' ? p.b : ptAtAngle(p.center, p.radius, p.thetaEnd);

                  /** هل θ داخل القوس (داخلياً صرفاً)؟ */
                  function isAngleInsideArc(theta: number, thetaStart: number, dTheta: number): boolean {
                    if (Math.abs(dTheta) < EPS_LEN) return false;
                      let d = theta - thetaStart;
                        while (d > Math.PI) d -= 2 * Math.PI;
                          while (d < -Math.PI) d += 2 * Math.PI;
                            return dTheta > 0
                                ? d > EPS_LEN && d < dTheta - EPS_LEN
                                    : d < -EPS_LEN && d > dTheta + EPS_LEN;
                                    }

                                    // ============ كشف التقاطعات ============
                                    function segsIntersect(a1: Point, a2: Point, b1: Point, b2: Point): boolean {
                                      const d1x = a2.x - a1.x, d1y = a2.y - a1.y;
                                        const d2x = b2.x - b1.x, d2y = b2.y - b1.y;
                                          const den = d1x * d2y - d1y * d2x;
                                            if (Math.abs(den) < EPS_DET) return false;
                                              const t = ((b1.x - a1.x) * d2y - (b1.y - a1.y) * d2x) / den;
                                                const u = ((b1.x - a1.x) * d1y - (b1.y - a1.y) * d1x) / den;
                                                  return t > EPS_LEN && t < 1 - EPS_LEN && u > EPS_LEN && u < 1 - EPS_LEN;
                                                  }

                                                  function lineArcIntersect(l: LinePrim, a: ArcPrim): boolean {
                                                    const dx = l.b.x - l.a.x, dy = l.b.y - l.a.y;
                                                      const fx = l.a.x - a.center.x, fy = l.a.y - a.center.y;
                                                        const A = dx * dx + dy * dy;
                                                          if (A < EPS_LEN) return false;
                                                            const B = 2 * (fx * dx + fy * dy);
                                                              const C = fx * fx + fy * fy - a.radius * a.radius;
                                                                const disc = B * B - 4 * A * C;
                                                                  if (disc < -EPS_DET) return false;
                                                                    const sq = Math.sqrt(Math.max(0, disc));
                                                                      const dT = a.thetaEnd - a.thetaStart;
                                                                        for (const t of [(-B - sq) / (2 * A), (-B + sq) / (2 * A)]) {
                                                                            if (t <= EPS_LEN || t >= 1 - EPS_LEN) continue;
                                                                                const th = Math.atan2(l.a.y + t * dy - a.center.y, l.a.x + t * dx - a.center.x);
                                                                                    if (isAngleInsideArc(th, a.thetaStart, dT)) return true;
                                                                                      }
                                                                                        return false;
                                                                                        }

                                                                                        function arcArcIntersect(a1: ArcPrim, a2: ArcPrim): boolean {
                                                                                          const dx = a2.center.x - a1.center.x, dy = a2.center.y - a1.center.y;
                                                                                            const d = Math.hypot(dx, dy);
                                                                                              if (d > a1.radius + a2.radius + EPS_DET) return false;
                                                                                                if (d < Math.abs(a1.radius - a2.radius) - EPS_DET) return false;
                                                                                                  if (d < EPS_LEN) return false;

                                                                                                    const a = (a1.radius ** 2 - a2.radius ** 2 + d * d) / (2 * d);
                                                                                                      const h2 = a1.radius ** 2 - a * a;
                                                                                                        if (h2 < -EPS_DET) return false;
                                                                                                          const h = Math.sqrt(Math.max(0, h2));
                                                                                                            const mx = a1.center.x + (a * dx) / d;
                                                                                                              const my = a1.center.y + (a * dy) / d;
                                                                                                                const d1 = a1.thetaEnd - a1.thetaStart;
                                                                                                                  const d2 = a2.thetaEnd - a2.thetaStart;

                                                                                                                    for (const s of [1, -1]) {
                                                                                                                        const px = mx + s * (h * dy) / d;
                                                                                                                            const py = my - s * (h * dx) / d;
                                                                                                                                const t1 = Math.atan2(py - a1.center.y, px - a1.center.x);
                                                                                                                                    const t2 = Math.atan2(py - a2.center.y, px - a2.center.x);
                                                                                                                                        if (isAngleInsideArc(t1, a1.thetaStart, d1) && isAngleInsideArc(t2, a2.thetaStart, d2)) return true;
                                                                                                                                          }
                                                                                                                                            return false;
                                                                                                                                            }

                                                                                                                                            function primsIntersect(p1: Primitive, p2: Primitive): boolean {
                                                                                                                                              if (p1.kind === 'line' && p2.kind === 'line') return segsIntersect(p1.a, p1.b, p2.a, p2.b);
                                                                                                                                                if (p1.kind === 'line') return lineArcIntersect(p1, p2 as ArcPrim);
                                                                                                                                                  if (p2.kind === 'line') return lineArcIntersect(p2, p1 as ArcPrim);
                                                                                                                                                    return arcArcIntersect(p1, p2);
                                                                                                                                                    }

                                                                                                                                                    function hasSelfIntersection(prims: Primitive[]): boolean {
                                                                                                                                                      const m = prims.length;
                                                                                                                                                        for (let i = 0; i < m; i++) {
                                                                                                                                                            for (let j = i + 1; j < m; j++) {
                                                                                                                                                                  if (j === i + 1 || (i === 0 && j === m - 1)) continue;
                                                                                                                                                                        if (primsIntersect(prims[i], prims[j])) return true;
                                                                                                                                                                            }
                                                                                                                                                                              }
                                                                                                                                                                                return false;
                                                                                                                                                                                }

                                                                                                                                                                                // ============ بناء الحافة الهندسية لجدار ============
                                                                                                                                                                                function buildWallFace(w: Wall, reversed: boolean, loopIsCCW: boolean): WallFace | null {
                                                                                                                                                                                  if (!w.curveRadius) {
                                                                                                                                                                                      const rect = wallRectangle(w);
                                                                                                                                                                                          let a = { ...rect.faces[0].start }, b = { ...rect.faces[0].end };
                                                                                                                                                                                              if (reversed) [a, b] = [b, a];
                                                                                                                                                                                                  const dx = b.x - a.x, dy = b.y - a.y;
                                                                                                                                                                                                      const len = Math.hypot(dx, dy);
                                                                                                                                                                                                          if (len < EPS_LEN) return null;
                                                                                                                                                                                                              const t = { x: dx / len, y: dy / len };
                                                                                                                                                                                                                  return { startPoint: a, endPoint: b, startTangent: t, endTangent: t };
                                                                                                                                                                                                                    }

                                                                                                                                                                                                                      const geo = getCurvedWallGeometry(w);
                                                                                                                                                                                                                        if (!geo) return null;

                                                                                                                                                                                                                          const thetaStart = reversed ? geo.endAngle : geo.startAngle;
                                                                                                                                                                                                                            const thetaEndRaw = reversed ? geo.startAngle : geo.endAngle;
                                                                                                                                                                                                                              let dTheta = thetaEndRaw - thetaStart;
                                                                                                                                                                                                                                while (dTheta > Math.PI) dTheta -= 2 * Math.PI;
                                                                                                                                                                                                                                  while (dTheta < -Math.PI) dTheta += 2 * Math.PI;
                                                                                                                                                                                                                                    if (Math.abs(dTheta) < EPS_LEN) return null;
                                                                                                                                                                                                                                      const thetaEnd = thetaStart + dTheta;

                                                                                                                                                                                                                                        // اشتقاق: center داخل المبنى ⟺ side·S·revSign = +1
                                                                                                                                                                                                                                          //   centerInside ⟹ outerRadius، وإلا innerRadius
                                                                                                                                                                                                                                            const side = geo.anticlockwise ? 1 : -1;
                                                                                                                                                                                                                                              const S = loopIsCCW ? 1 : -1;
                                                                                                                                                                                                                                                const revSign = reversed ? 1 : -1;
                                                                                                                                                                                                                                                  const R = (side * S * revSign === 1) ? geo.outerRadius : geo.innerRadius;
                                                                                                                                                                                                                                                    if (R < EPS_LEN) return null;

                                                                                                                                                                                                                                                      const T = dTheta > 0 ? 1 : -1;
                                                                                                                                                                                                                                                        return {
                                                                                                                                                                                                                                                            startPoint: ptAtAngle(geo.center, R, thetaStart),
                                                                                                                                                                                                                                                                endPoint: ptAtAngle(geo.center, R, thetaEnd),
                                                                                                                                                                                                                                                                    startTangent: { x: -T * Math.sin(thetaStart), y: T * Math.cos(thetaStart) },
                                                                                                                                                                                                                                                                        endTangent: { x: -T * Math.sin(thetaEnd), y: T * Math.cos(thetaEnd) },
                                                                                                                                                                                                                                                                            arc: { center: geo.center, radius: R, thetaStart, thetaEnd },
                                                                                                                                                                                                                                                                              };
                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                              // ============ بناء الحدود ============
                                                                                                                                                                                                                                                                              type BuildResult = { prims: Primitive[]; valid: true } | { prims: null; valid: false; reason: string };

                                                                                                                                                                                                                                                                              function buildBoundary(walls: Wall[]): BuildResult {
                                                                                                                                                                                                                                                                                const ordered = orderWallsIntoLoop(walls);
                                                                                                                                                                                                                                                                                  const n = ordered.length;
                                                                                                                                                                                                                                                                                    if (n < 3 || n !== walls.length) return { prims: null, valid: false, reason: 'loop_not_closed_or_incomplete' };

                                                                                                                                                                                                                                                                                      // فحص إغلاق الحلقة الأصلية
                                                                                                                                                                                                                                                                                        for (let i = 0; i < n; i++) {
                                                                                                                                                                                                                                                                                            const c = ordered[i], nx = ordered[(i + 1) % n];
                                                                                                                                                                                                                                                                                                const cEnd = c.reversed ? c.wall.start : c.wall.end;
                                                                                                                                                                                                                                                                                                    const nStart = nx.reversed ? nx.wall.end : nx.wall.start;
                                                                                                                                                                                                                                                                                                        if (dist2D(cEnd, nStart) > LOOP_TOL) return { prims: null, valid: false, reason: 'loop_gap_too_large' };
                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                            // اتجاه الحلقة (Shoelace على الأوتار)
                                                                                                                                                                                                                                                                                                              let signed = 0;
                                                                                                                                                                                                                                                                                                                for (const o of ordered) {
                                                                                                                                                                                                                                                                                                                    const p1 = o.reversed ? o.wall.end : o.wall.start;
                                                                                                                                                                                                                                                                                                                        const p2 = o.reversed ? o.wall.start : o.wall.end;
                                                                                                                                                                                                                                                                                                                            signed += p1.x * p2.y - p2.x * p1.y;
                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                if (Math.abs(signed) < EPS_DET) return { prims: null, valid: false, reason: 'degenerate_loop' };
                                                                                                                                                                                                                                                                                                                                  const loopIsCCW = signed > 0;

                                                                                                                                                                                                                                                                                                                                    const faces: WallFace[] = [];
                                                                                                                                                                                                                                                                                                                                      for (const o of ordered) {
                                                                                                                                                                                                                                                                                                                                          const f = buildWallFace(o.wall, o.reversed, loopIsCCW);
                                                                                                                                                                                                                                                                                                                                              if (!f) return { prims: null, valid: false, reason: 'invalid_wall_face' };
                                                                                                                                                                                                                                                                                                                                                  faces.push(f);
                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                      const prims: Primitive[] = [];

                                                                                                                                                                                                                                                                                                                                                        for (let i = 0; i < n; i++) {
                                                                                                                                                                                                                                                                                                                                                            const f = faces[i], nf = faces[(i + 1) % n];

                                                                                                                                                                                                                                                                                                                                                                // Wall primitive
                                                                                                                                                                                                                                                                                                                                                                    if (f.arc) {
                                                                                                                                                                                                                                                                                                                                                                          prims.push({ kind: 'arc', ...f.arc });
                                                                                                                                                                                                                                                                                                                                                                              } else if (dist2D(f.startPoint, f.endPoint) > EPS_POINT) {
                                                                                                                                                                                                                                                                                                                                                                                    prims.push({ kind: 'line', a: f.startPoint, b: f.endPoint });
                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                            // Corner: Miter أو Bevel
                                                                                                                                                                                                                                                                                                                                                                                                const det = f.endTangent.x * nf.startTangent.y - f.endTangent.y * nf.startTangent.x;
                                                                                                                                                                                                                                                                                                                                                                                                    const maxTh = Math.max(ordered[i].wall.thickness, ordered[(i + 1) % n].wall.thickness);

                                                                                                                                                                                                                                                                                                                                                                                                        if (Math.abs(det) < EPS_DET) {
                                                                                                                                                                                                                                                                                                                                                                                                              if (dist2D(f.endPoint, nf.startPoint) > EPS_POINT) {
                                                                                                                                                                                                                                                                                                                                                                                                                      prims.push({ kind: 'line', a: f.endPoint, b: nf.startPoint });
                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                  continue;
                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                          const t = ((nf.startPoint.x - f.endPoint.x) * nf.startTangent.y
                                                                                                                                                                                                                                                                                                                                                                                                                                                       - (nf.startPoint.y - f.endPoint.y) * nf.startTangent.x) / det;
                                                                                                                                                                                                                                                                                                                                                                                                                                                           const inter = { x: f.endPoint.x + t * f.endTangent.x, y: f.endPoint.y + t * f.endTangent.y };
                                                                                                                                                                                                                                                                                                                                                                                                                                                               const miterDist = dist2D(inter, f.endPoint);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                   if (miterDist < (maxTh / 2) * 2.5) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                         // Miter: وصلتان صريحتان
                                                                                                                                                                                                                                                                                                                                                                                                                                                                               if (miterDist > EPS_POINT) prims.push({ kind: 'line', a: f.endPoint, b: inter });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     if (dist2D(inter, nf.startPoint) > EPS_POINT) prims.push({ kind: 'line', a: inter, b: nf.startPoint });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               // Bevel fallback
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     if (dist2D(f.endPoint, nf.startPoint) > EPS_POINT) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             prims.push({ kind: 'line', a: f.endPoint, b: nf.startPoint });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           const filtered = prims.filter(p => p.kind === 'line'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               ? dist2D(p.a, p.b) > EPS_POINT
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   : Math.abs(p.thetaEnd - p.thetaStart) > EPS_LEN && p.radius > EPS_LEN);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     if (filtered.length < 3) return { prims: null, valid: false, reason: 'too_few_primitives' };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       // فحص الاتصال المتسلسل
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         for (let i = 0; i < filtered.length; i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             if (dist2D(primEnd(filtered[i]), primStart(filtered[(i + 1) % filtered.length])) > TOL_CONNECT) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   return { prims: null, valid: false, reason: 'connectivity_broken' };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           if (hasSelfIntersection(filtered)) return { prims: null, valid: false, reason: 'self_intersection' };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             const signedArea = greensArea(filtered);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               if (Math.abs(signedArea) < EPS_DET) return { prims: null, valid: false, reason: 'degenerate_area' };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 if ((signedArea > 0) !== loopIsCCW) return { prims: null, valid: false, reason: 'orientation_mismatch' };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   return { prims: filtered, valid: true };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   // ============ قانون جرين ============
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   function greensArea(prims: Primitive[]): number {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     let area = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       for (const p of prims) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           if (p.kind === 'line') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 area += 0.5 * (p.a.x * p.b.y - p.b.x * p.a.y);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           const x1 = p.center.x + p.radius * Math.cos(p.thetaStart);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 const y1 = p.center.y + p.radius * Math.sin(p.thetaStart);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       const x2 = p.center.x + p.radius * Math.cos(p.thetaEnd);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             const y2 = p.center.y + p.radius * Math.sin(p.thetaEnd);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   const dT = p.thetaEnd - p.thetaStart;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         area += 0.5 * (p.center.x * (y2 - y1) - p.center.y * (x2 - x1) + p.radius * p.radius * dT);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 return area;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 // ============ API عام ============
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 export interface ExactAreaResult {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   area: number;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     valid: boolean;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       reason?: string;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }
                                                                   export function computeExactContourAreaDetailed(walls: Wall[]): ExactAreaResult {
                                                                       const polygon = buildContourPolygon(walls, 0);
                                                                         const approxArea = polygonArea(polygon);

                                                                           const built = buildBoundary(walls);
                                                                             if (!built.valid) {
                                                                                 // ✅ fallback: أظهر المساحة التقريبية بدل صفر
                                                                                     if (approxArea > MIN_AREA) {
                                                                                           return { area: approxArea, valid: false, reason: `fallback:${built.reason}` };
                                                                                               }
                                                                                                   return { area: 0, valid: false, reason: built.reason };
                                                                                                     }

                                                                                                       const area = Math.abs(greensArea(built.prims));
                                                                                                         if (!Number.isFinite(area)) {
                                                                                                             return { area: approxArea, valid: false, reason: 'non_finite_area' };
                                                                                                               }
                                                                                                                 if (area < MIN_AREA) {
                                                                                                                     return { area: approxArea, valid: false, reason: 'below_min_area' };
                                                                                                                       }
                                                                                                                         return { area, valid: true };
                                                                                                                         }
                                                                   
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       export function computeExactContourArea(walls: Wall[]): number {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     return computeExactContourAreaDetailed(walls).area;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     export function computeContourPerimeter(walls: Wall[]): number {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       return walls.reduce((s, w) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           if (!w.curveRadius) return s + distance(w.start, w.end);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               const geo = getCurvedWallGeometry(w);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   if (!geo) return s + distance(w.start, w.end);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       const span = geo.anticlockwise ? geo.startAngle - geo.endAngle : geo.endAngle - geo.startAngle;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           return s + Math.abs(span) * (geo.radius + w.thickness / 2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             }, 0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             export interface ContourMeasurements {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               polygon: Point[];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 perimeter: number;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   area: number;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     count: number;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       areaValid: boolean;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         areaReason?: string;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         export function computeContourProps(walls: Wall[]): ContourMeasurements {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           const detailed = computeExactContourAreaDetailed(walls);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             return {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 polygon: buildContourPolygon(walls, 0),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     perimeter: computeContourPerimeter(walls),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         area: detailed.area,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             count: walls.length,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 areaValid: detailed.valid,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     areaReason: detailed.reason,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       